import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Comparator;
import java.util.stream.Stream;

public class SafeFileWriterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void write(Path target, String content) {
        try {
            SafeFileWriter.writeAtomically(target, content);
        } catch (Exception e) {
            System.out.println("FAIL  writeAtomically threw " + e.getClass().getSimpleName());
            failures++;
        }
    }

    static String read(Path file) {
        try {
            return Files.exists(file) ? Files.readString(file, StandardCharsets.UTF_8) : "<no file>";
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    static long entriesIn(Path dir) {
        try (Stream<Path> paths = Files.list(dir)) {
            return paths.count();
        } catch (Exception e) {
            return -1L;
        }
    }

    public static void main(String[] args) throws Exception {
        Path dir = Files.createTempDirectory("safewrite");
        try {
            Path target = dir.resolve("config.txt");

            write(target, "v1");
            check("file created", "v1", read(target));
            check("no leftovers after the first write", 1L, entriesIn(dir));

            write(target, "v2 is longer than v1");
            check("file replaced", "v2 is longer than v1", read(target));
            check("no leftovers after the second write", 1L, entriesIn(dir));

            write(target, "shorter");
            check("old bytes fully gone", "shorter", read(target));

            write(target, "");
            check("empty content", "", read(target));

            write(target, "line one\nline two\n");
            check("multi line content", "line one\nline two\n", read(target));

            Path other = dir.resolve("second.txt");
            write(other, "hello");
            check("second file written", "hello", read(other));
            check("directory holds exactly the two targets", 2L, entriesIn(dir));
        } finally {
            try (Stream<Path> paths = Files.walk(dir)) {
                for (Path p : paths.sorted(Comparator.reverseOrder()).toList()) {
                    Files.deleteIfExists(p);
                }
            }
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

